import os
import sqlite3
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/app/data/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        email TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        api_key TEXT,
        department TEXT
    )''')
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key, department) VALUES ('admin', 'admin@corp.internal', 'superadmin', 'sk-admin-9f8e7d6c', 'engineering')")
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key, department) VALUES ('svc-deploy', 'deploy@corp.internal', 'service', 'sk-deploy-1a2b3c4d', 'platform')")
    db.execute("INSERT OR IGNORE INTO users (username, email, role, api_key, department) VALUES ('jsmith', 'jsmith@corp.internal', 'user', 'sk-user-5e6f7a8b', 'marketing')")
    db.commit()
    db.close()

@app.before_request
def check_api_key():
    # Internal service mesh handles primary AuthN
    # This is defense-in-depth: validate caller has a key format
    key = request.headers.get('X-Api-Key', '')
    if not key.startswith('sk-'):
        return jsonify({'error': 'invalid key format'}), 401

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department or role.
    Supports flexible filtering for internal dashboards."""
    department = request.args.get('department', '')
    role = request.args.get('role', '')

    # Build query with filters
    conditions = []
    if department:
        conditions.append(f"department = '{department}'")
    if role:
        conditions.append(f"role = '{role}'")

    query = "SELECT username, email, department, role FROM users"
    if conditions:
        query += " WHERE " + " AND ".join(conditions)

    try:
        db = get_db()
        cursor = db.execute(query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'users': results, 'count': len(results)})
    except Exception as e:
        return jsonify({'error': 'query failed', 'detail': str(e)}), 500

@app.route('/api/users/<username>/profile', methods=['GET'])
def get_profile(username):
    """Get user profile - excludes sensitive fields."""
    db = get_db()
    cursor = db.execute(
        "SELECT username, email, department, role FROM users WHERE username = ?",
        (username,)
    )
    user = cursor.fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    data = request.get_json()
    if not data or 'username' not in data or 'email' not in data:
        return jsonify({'error': 'missing fields'}), 400

    dept = data.get('department', 'general')
    # Prevent role escalation - new users always get 'user' role
    try:
        db = get_db()
        db.execute(
            "INSERT INTO users (username, email, department, role) VALUES (?, ?, ?, 'user')",
            (data['username'], data['email'], dept)
        )
        db.commit()
        return jsonify({'status': 'created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'username exists'}), 409

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    os.makedirs('/var/app/data', exist_ok=True)
    init_db()
    app.run(host='0.0.0.0', port=8080)
